const n=(key,label,answer,tolerance=.001)=>({key,label,type:'number',answer,tolerance});
const s=(key,label,answer,options)=>({key,label,type:'select',answer,options});
export const finalLabs={
 river:{prompt:'Rectangular teaching channel: width4m, mean depth0.3m, mean velocity0.5m/s. Enter area and discharge.',fields:[n('area','Cross-sectional area /m²',1.2),n('flow','Discharge /m³/s',.6)],hint:'Area = width × mean depth; discharge = area × mean velocity.'},
 coast:{prompt:'Teaching beach rises2m over20m of horizontal run. Enter the denominator of1:n, then choose an unbiased sediment method.',fields:[n('gradient','Gradient denominator n',10),s('sample','Sediment sampling rule','systematic',[['largest','Choose only the biggest pebbles'],['systematic','Stated interval/sample across the site'],['pretty','Choose attractive colours']])],hint:'Simplify rise:run; sample by a consistent rule rather than by appearance.'},
 urban:{prompt:'Eight retail premises among20surveyed. Calculate the percentage and select the source needed for Census change.',fields:[n('share','Retail premises /%',40),s('source','Census comparison','matched',[['likes','Undated social-media likes'],['matched','Dated comparable Census geographies'],['guess','Guess from a shop photograph']])],hint:'Divide the category count by the total and multiply by100. Compare matching dated areas.'},
 rural:{prompt:'SiteA:18people/6minutes; SiteB:30people/10minutes. Enter both rates.',fields:[n('rateA','SiteA /people per minute',3),n('rateB','SiteB /people per minute',3)],hint:'Divide each count by its own duration; equal rates can have unequal raw totals.'},
 maps:{prompt:'Annotate the teaching sketch: houses follow the east-bank road. Choose a road symbol and a useful note.',fields:[s('symbol','Road key','line',[['dot','A dot labelled river'],['line','A line labelled road'],['blank','No stated symbol']]),s('note','Placed annotation','pattern',[['nice','A nice place'],['pattern','Homes follow the east-bank road'],['rate','Floods happen every100years exactly']])],hint:'Use an explicit symbol key and an annotation tied to the mapped spatial pattern.'},
 relief:{prompt:'Point P lies at easting23.4km and northing46.7km in the teaching grid. A route measures4cm at1:25000. Enter the six figures and route length.',fields:[{key:'grid',label:'Six-figure reference (no spaces)',type:'text',answer:'234467'},n('distance','Ground route length /km',1)],hint:'Read eastings then northings, with tenths. At1:25000,1cm represents250m.'},
 photos:{prompt:'The teaching map states the camera faces east. Decide image-left direction and which claim the High Force photo supports.',fields:[s('direction','Direction to camera left','north',[['west','West'],['north','North'],['south','South']]),s('claim','Supported observation','waterfall',[['rate','Exactly2m annual retreat'],['waterfall','Waterfall and pool are visible'],['flood','All catchment homes flooded']])],hint:'Rotate the compass from the stated camera direction. A single photo supports visible features, not a measured rate.'},
 gis:{prompt:'Join the actual retained Amazonas polygon to its2024annual PRODES record. Select its compatible code and year, then enter the displayed area.',fields:[s('code','State code','BR-AM',[['BR-PA','BR-PA · Pará'],['BR-AM','BR-AM · Amazonas'],['BR-MT','BR-MT · Mato Grosso'],['BR-RO','BR-RO · Rondônia']]),s('year','PRODES year','2024',[['2023','2023'],['2024','2024']]),n('area','Annual monitored clearance /km²',1223)],hint:'Match the state code, selected year and km²indicator. Regional colouring is not a map of exact clearings.'},
 graphs:{prompt:'Build zero-based category bars for A4people, B8people, C12people. Enter values, choose a sufficient vertical maximum and state the unit.',fields:[s('chart','Representation for these categories','bar',[['bar','Category bars'],['line','Explore an ordered time-series line'],['pie','Explore parts of the total'],['pictogram','Explore a pictogram (one symbol =4)'],['histogram','Explore equal-width continuous bins']]),n('a','CategoryA /people',4),n('b','CategoryB /people',8),n('c','CategoryC /people',12),{...n('maximum','Vertical axis maximum',12),minAnswer:12,maxAnswer:24},s('unit','Vertical axis unit','people',[['percent','Percentage (no denominator supplied)'],['people','People'],['metres','Metres']])],hint:'Copy each count to its own category. Start at zero, fit all bars and label people; axis maximum12–24is accepted.'},
 units:{prompt:'Convert0.5km² to m² and a1in200annual probability to percent.',fields:[n('area','Area /m²',500000),n('probability','Annual probability /%',.5)],hint:'Square the1000m/km conversion. Probability percent =100divided by the return period.'},
 statistics:{prompt:'Use median-of-halves for ordered2,4,6,8,10,12,14,16. Enter Q1,Q3and IQR.',fields:[n('q1','Lower quartile',5),n('q3','Upper quartile',13),n('iqr','Interquartile range',8)],hint:'Median of lower four gives Q1; median of upper four gives Q3. IQR=Q3−Q1.'},
 bivariate:{prompt:'Fit the simple teaching trend through(1,3),(2,5),(3,7),(4,9),(5,11). Enter slope and intercept for y=mx+c, then predict at x3.',fields:[n('slope','Slope m',2),n('intercept','Intercept c',1),n('prediction','Predicted y at x3',7)],hint:'The points rise2for each1in x. Extend that line to x0to find the intercept; predictions follow y=mx+c.'},
 reasoning:{prompt:'Choose the command and evidence role, then write an explanation draft. This writing is saved locally and UNMARKED: checking only verifies your selections and that a draft exists.',fields:[s('command','A how-or-why question needs','explain',[['describe','Describe only visible characteristics'],['explain','Explain using a reasoned mechanism'],['name','Name without a reason']]),s('evidence','Role of evidence','support',[['replace','Replace the causal explanation'],['support','Support and exemplify the explanation'],['decoration','Decorate the paragraph']]),{key:'draft',label:'Your explanation draft · unmarked',type:'textarea',minLength:30}],hint:'Explain a causal chain with evidence, then self-review: does it answer the question, link cause to effect and acknowledge limits? Text quality is not automatically marked.'},
 footprints:{prompt:'Teaching factors only:100kWh×0.2kgCO2e/kWh plus50passenger-km×0.1kgCO2e/passenger-km. Separately calculate1000kg÷500kg/ha×1.5gha/ha, then divide by2gha biocapacity.',fields:[n('carbon','Carbon total /kgCO2e',25),n('ecological','Toy ecological footprint /gha',3),n('ratio','Demand /biocapacity ratio',1.5)],hint:'Carbon: add compatible activity×factor products. Area: demand/yield, then normalise; compare gha/gha separately.'}
};
export const labSlug=k=>k.replace('dev-final-','');
export function gradeFinalLab(kind,draft){const conf=finalLabs[labSlug(kind)];if(!conf)return {passed:true,missing:[]};const d=draft&&typeof draft==='object'&&!Array.isArray(draft)?draft:{};const missing=conf.fields.filter(f=>{const x=d[f.key];if(f.type==='number'){if(x===undefined||x===null||String(x).trim()==='')return true;const v=Number(x);return !Number.isFinite(v)||(f.minAnswer!==undefined?v<f.minAnswer||v>f.maxAnswer:Math.abs(v-f.answer)>f.tolerance);}if(f.type==='textarea')return typeof x!=='string'||x.trim().length<f.minLength;return String(x??'').trim()!==f.answer;}).map(f=>f.key);return {passed:d.checked===true&&missing.length===0,missing};}
export const passedFinalLab=(l,p)=>!l.labRequired||gradeFinalLab(l.model,p.finalLab).passed;
export const exampleLabDraft=kind=>({checked:true,...Object.fromEntries(finalLabs[labSlug(kind)].fields.map(f=>[f.key,f.type==='textarea'?'Impermeable surfaces limit infiltration, so more rain runs quickly into drains.':String(f.answer)]))});
